

-- Model: sat_erc_timesheet_curr
-- Description: Current active record for TIMESHEET from SAT_ERC_TIMESHEET
-- Generated: 2025-05-19 21:48:09

WITH MAX_DATE AS (
    SELECT
        TIMESHEET_HKEY,
        MAX() AS MAX_TRANS_DATE
    FROM {{ source('eli_dv_rv', 'sat_erc_timesheet') }}
    WHERE DELETE_FLAG = 'N'
    GROUP BY TIMESHEET_HKEY
)

SELECT
    SAT_SRC.TIMESHEET_HKEY,
    -- tagged: is_other_attr
    ADJUSTMENTREASON,
    ADMIN,
    ADVANCEPAID,
    APPROVEDBY,
    APPROVEDDATE,
    ASSIGNEEID,
    BH_TIMESHEET_ID,
    BILLED,
    BILLEDHOURS,
    BILLEDMARGINBASIS,
    BONUSPAID,
    DEDUCTAMOUNTFORMARGIN,
    DISCOUNT,
    ENABLEEXPENSEINPUT,
    ENABLETIMEINPUT,
    ENDDATE,
    EXPENSEBILLED,
    EXPENSECOMMENT,
    EXPENSELOAD,
    EXPENSEPAID,
    ISADJUSTMENT,
    ISAUTOCALCULATE,
    ISEXPORTED,
    ISIMPORTED,
    ISINVOICEDEXPENSES,
    ISINVOICEDHOURS,
    ISNEWBUSINESS,
    ISNOBILL,
    ISNOCOUNT,
    ISNOPAY,
    ISPENDINGADDITIONALAPPROVAL,
    ISPOSTED,
    ISVOIDED,
    ISWIPPOSTED,
    LASTNOTEID,
    MATCHRATESBURDENAMOUNT,
    PAID,
    PAIDHOURS,
    PAYPERIODENDDATE,
    POSTPROCESSINGACTIONID,
    POSTPROCESSINGUSERID,
    PROCESSINGSTATUSID,
    PROFIT,
    RANGECALENDARPERIODID,
    REJECTEDBY,
    REJECTEDDATE,
    REJECTIONCOUNT,
    REJECTREASONID,
    REQUIREMENTSBURDENAMOUNT,
    REQUIREMENTSBURDENONETIMEAPPLIED,
    SALESTAX,
    STARTDATE,
    SUBMITTEDBY,
    SUBMITTEDDATE,
    TAXACTUAL,
    TAXESTIMATED,
    TOTALHOURS,
    TOTALLOAD,
    VMSBURDEN,
    VMSBURDENDEDUCTEDFROMINVOICE,
    WORKCOMP,
    _FIVETRAN_ACTIVE,
    _FIVETRAN_END,
    _FIVETRAN_START
FROM {{ source('eli_dv_rv', 'sat_erc_timesheet') }} SAT_SRC
INNER JOIN MAX_DATE MD
    ON SAT_SRC.TIMESHEET_HKEY = MD.TIMESHEET_HKEY
    AND SAT_SRC. = MD.MAX_TRANS_DATE
    AND SAT_SRC.DELETE_FLAG = 'N'